import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Geometry – use image aspect ratio if possible, fallback to 1.6:1
  const imgAspect = 512 / 320;
  const width = 1.6;
  const height = width / imgAspect;
  const geometry = new PlaneGeometry(width, height);

  // Material – basic unlit unless lighting is requested (none here)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthTest: true,
    depthWrite: true,
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; material will update when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // No cinematic primitives for this node, but keep API compatibility
  const primitiveInstances = [];

  // No text content for this node
  // No interaction handlers
  root.userData.handlers = {};

  // Cleanup: dispose geometry, material and any GSAP timelines
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose any primitive resources
    primitiveInstances.forEach((inst) => {
      if (inst?.cleanup) inst.cleanup();
    });

    // Kill GSAP timelines if any were created
    gsap.globalTimeline.clear();
  };

  return root;
}
